        num_chunks = 1
        for nc in (32, 16, 8, 4, 2, 1):
            if N % nc == 0 and (N // nc) % 4 == 0:
                num_chunks = nc
                break
        sum_buf = torch.zeros(batch, dtype=torch.float64, device=x.device)
        sumsq_buf = torch.zeros(batch, dtype=torch.float64, device=x.device)
        counter_buf = torch.zeros(batch, dtype=torch.int32, device=x.device)
        mean_buf = torch.empty(batch, dtype=torch.float64, device=x.device)
        invstd_buf = torch.empty(batch, dtype=torch.float64, device=x.device)
        module = _get_ptx_module()
        stream = torch.cuda.current_stream(x.device)
        module.launch(
            "layer_norm_stats_kernel",
            grid=(batch, num_chunks, 1),
            block=(256, 1, 1),
            arguments=[x, u32(N), u32(num_chunks), f32(self.eps),
                       sum_buf, sumsq_buf, counter_buf, mean_buf, invstd_buf],
            shared_memory=0,
            stream=stream,
        )
        module.launch(
            "layer_norm_normalize_kernel",
            grid=(batch, num_chunks, 1),
            block=(256, 1, 1),
            arguments=[x, out, self.weight, self.bias, u32(N), u32(num_chunks),
                       mean_buf, invstd_buf],
            shared_memory=0,
            stream=stream,
        )
        return out
